<script setup lang="ts">
import {ref} from 'vue';import {ElMessage} from 'element-plus';import {login as signIn,isStaleAuthError} from '../api';
const username=ref('');const password=ref('');const busy=ref(false);
async function login(){if(busy.value)return;busy.value=true;try{await signIn(username.value,password.value);password.value='';}catch(e){if(!isStaleAuthError(e))ElMessage.error((e as Error).message);}finally{busy.value=false;}}
</script>
<template><div class="login-page"><section class="login-story"><div class="brand white"><span class="brand-mark">心</span><div>心伴随访<small>HEART FOLLOW-UP</small></div></div><div class="story-copy"><span class="eyebrow">让每一次随访都有回应</span><h1>把患者的近况，<br>带回医生的视野。</h1><p>患者在网页中说一说，您在这里看见、核对与回应。让院后的照护，保持连接。</p><div class="story-line"><span class="pulse"></span> 语音采集 · 信息留存 · 医生审核</div></div><div class="story-foot">心衰随访协作平台</div></section><section class="login-form"><div class="login-box"><span class="eyebrow">医生入口</span><h2>登录工作台</h2><p class="muted">使用管理员为您创建的账户</p><el-form label-position="top" @submit.prevent="login"><el-form-item label="账号" for="login-username"><el-input id="login-username" v-model="username" autocomplete="username" size="large" placeholder="请输入医生账号"/></el-form-item><el-form-item label="密码" for="login-password"><el-input id="login-password" v-model="password" type="password" show-password autocomplete="current-password" size="large" placeholder="请输入密码"/></el-form-item><el-button aria-label="登录工作台" native-type="submit" type="primary" size="large" :loading="busy" class="full-width">登录工作台 <span class="arrow">→</span></el-button></el-form><p class="login-help">账户开通或密码问题，请联系平台管理员。</p><a class="patient-web-link" href="/patient/" target="_blank" rel="noopener noreferrer">前往患者网站 ↗</a></div></section></div></template>
